this.form.addEventListener("keydown", event => {
  // Prevent scrolling of the html tag when space is used on a button or
  // checkbox.
  if (
    event.key == " " &&
    ["button", "checkbox"].includes(document.activeElement.type)
  ) {
    event.preventDefault();
  }

  if (event.key != "Escape") {
    return;
  }

  event.preventDefault();
  this.form.reset();
});
